"""
Algorithm 1 -- Closed-Form Maximal Cascade Depth with Frontier Certificate.

Computes d_max(B, T) = floor(log_B((B-1)T + 1)) - 1, the greatest depth d with
S_B(d) = 1 + B + ... + B^d <= T, and returns a machine-checkable certificate of
maximality: the pair (S_B(d), S_B(d+1)) together with the verified sandwich
S_B(d) <= T < S_B(d+1).
"""

from __future__ import annotations

from dataclasses import dataclass


def cascade_cells(B: int, d: int) -> int:
    """S_B(d) = 1 + B + ... + B^d, in closed form.  O(log d) big-int operations."""
    if B < 2:
        raise ValueError("branching number must satisfy B >= 2")
    if d < 0:
        raise ValueError("depth must be non-negative")
    return (B ** (d + 1) - 1) // (B - 1)


def integer_log(B: int, n: int) -> int:
    """Greatest m with B^m <= n (with integer_log(B, n) = 0 for n < 1).

    Doubling then binary refinement: O(log log n) multiplications of big integers.
    """
    if B < 2:
        raise ValueError("base must satisfy B >= 2")
    if n < 1:
        return 0
    # phase 1: double the exponent until we overshoot
    lo, hi = 0, 1
    while B ** hi <= n:
        lo, hi = hi, 2 * hi
    # phase 2: binary search for the frontier in (lo, hi]
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if B ** mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


@dataclass(frozen=True)
class DepthCertificate:
    """A maximality certificate for the parameter-derived depth."""
    branching: int
    threshold: int
    depth: int
    cells_at_depth: int
    cells_at_next: int

    @property
    def valid(self) -> bool:
        """True exactly when S_B(d) <= T < S_B(d+1), i.e. d is THE greatest depth."""
        return self.cells_at_depth <= self.threshold < self.cells_at_next

    def __str__(self) -> str:
        return (f"B={self.branching}, T={self.threshold}: d_max={self.depth}  "
                f"[{self.cells_at_depth} <= {self.threshold} < {self.cells_at_next}]  "
                f"{'certified' if self.valid else 'INVALID'}")


def parameter_depth(B: int, T: int) -> int:
    """The parameter-derived depth in closed form.

    Correctness rests on the finite geometric identity (B-1) S_B(d) + 1 = B^(d+1),
    which converts the budget inequality S_B(d) <= T into the power inequality
    B^(d+1) <= (B-1)T + 1, i.e. d + 1 <= floor(log_B((B-1)T+1)).

    Complexity: O(log log T) big-integer operations -- exponentially faster than the
    naive level-by-level accumulation, which costs O(log T) steps.
    """
    if B < 2:
        raise ValueError("branching number must satisfy B >= 2")
    if T < 1:
        raise ValueError("threshold must satisfy T >= 1")
    return integer_log(B, (B - 1) * T + 1) - 1


def certified_parameter_depth(B: int, T: int) -> DepthCertificate:
    """Compute the maximal depth and its frontier certificate."""
    d = parameter_depth(B, T)
    return DepthCertificate(B, T, d, cascade_cells(B, d), cascade_cells(B, d + 1))


if __name__ == "__main__":
    for B, T in [(2, 1000), (3, 100), (10, 10 ** 6), (5, 10 ** 6), (7, 10 ** 30)]:
        cert = certified_parameter_depth(B, T)
        assert cert.valid
        print(cert)
